def draw_node_for_search(node: GreasePencilTreeNode, layout: UILayout, grease_pencil: GreasePencil):
    if isinstance(node, GreasePencilLayerGroup):
        op = layout.operator('grease_pencil.move_to_layer', text=iface_('Add New Layer to {:s}').format(node.name), icon='ADD', translate=False)
        op.add_new_layer = True
        op.target_group_name = node.name
        for child in reversed(node.children):
            draw_node_for_search(child, layout, grease_pencil)
    elif isinstance(node, GreasePencilLayer):
        if node == grease_pencil.layers.active:
            icon = 'GREASEPENCIL'
        else:
            icon = 'NONE'
        layout.operator('grease_pencil.move_to_layer', text=node.name, icon=icon).target_layer_name = node.name

@staticmethod
def _icon_value_from_icon_handle(icon_name):
    import os
    if icon_name is not None:
        assert type(icon_name) is str
        icon_value = _icon_cache.get(icon_name)
        if icon_value is None:
            dirname = bpy.utils.system_resource('DATAFILES', path='icons')
            filepath = os.path.join(dirname, icon_name + '.dat')
            try:
                icon_value = bpy.app.icons.new_triangles_from_file(filepath)
            except Exception as ex:
                if not os.path.exists(filepath):
                    print('Missing icons:', filepath, ex)
                else:
                    print('Corrupt icon:', filepath, ex)
                if icon_name != 'none':
                    icon_value = ToolSelectPanelHelper._icon_value_from_icon_handle('none')
                else:
                    icon_value = 0
            _icon_cache[icon_name] = icon_value
        return icon_value
    else:
        return 0

